import{_ as a,a as s,a3 as i,o as l}from"./chunks/framework.yJBLK5ap.js";const m=JSON.parse('{"title":"Dali split deployment (Dali-only + app release)","description":"","frontmatter":{},"headers":[],"relativePath":"helm/examples/dali-split-same-namespace/README.md","filePath":"helm/examples/dali-split-same-namespace/README.md","lastUpdated":1795797312000}'),t={name:"helm/examples/dali-split-same-namespace/README.md"};function o(n,e,d,r,c,p){return l(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="dali-split-deployment-dali-only-app-release" tabindex="-1">Dali split deployment (Dali-only + app release) <a class="header-anchor" href="#dali-split-deployment-dali-only-app-release" aria-label="Permalink to &quot;Dali split deployment (Dali-only + app release)&quot;">​</a></h1><p>This example deploys HPCC in two releases:</p><ol><li>A Dali-only release that owns the Dali StatefulSet.</li><li>An application release that runs the rest of the HPCC stack without a local Dali entry and points its Dali clients at the first release via <code>global.externalDaliSvc</code>.</li></ol><p>This pattern uses <code>hpcc.getDali</code>. The application release points at the Dali-only release with <code>externalDaliSvc</code>, a <code>host:port</code> endpoint that can be set globally or on an individual component.</p><ul><li>Dali clients read the Dali endpoint from component-level <code>externalDaliSvc</code>, falling back to <code>global.externalDaliSvc</code> (<code>host:port</code>).</li><li><code>global.externalDaliSvc</code> is set on the app release only; the Dali-only release still defines its own <code>values.dali[]</code> entry so it can create the StatefulSet.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Kubernetes cluster and namespace create permissions</li><li>Helm 3</li><li>This example deploys both releases to the same namespace and uses the same-namespace service-name shorthand <code>mydali:7070</code>.</li><li>Commands omit <code>-n</code>/<code>--namespace</code> flags and use the current kubectl context; ensure your context is configured for the target namespace.</li></ul><h2 id="values-files" tabindex="-1">Values files <a class="header-anchor" href="#values-files" aria-label="Permalink to &quot;Values files&quot;">​</a></h2><ul><li><code>values-dali-only.yaml</code>: deploys only Dali StatefulSet (no ESP/Thor/Roxie/ECLAgent/etc).</li><li><code>values-no-dali.yaml</code>: deploys normal app stack with no local Dali entry; sets <code>global.externalDaliSvc</code> to point at the Dali-only release&#39;s service.</li></ul><h2 id="namespace-resource-ownership" tabindex="-1">Namespace resource ownership <a class="header-anchor" href="#namespace-resource-ownership" aria-label="Permalink to &quot;Namespace resource ownership&quot;">​</a></h2><p>The release containing an enabled entry in <code>values.dali[]</code> automatically owns the namespace-wide, fixed-name base policies and shared ServiceAccounts/Roles/RoleBindings. The app release does not recreate those resources; it generates policies for its active ESP and Sasha components instead. Configure namespace-wide egress settings such as <code>global.egress.restricted</code>, <code>kubeSystemLabel</code>, <code>kubeApiCidr</code>, and <code>kubeApiPort</code> on the Dali-owning release; that release alone renders the base NetworkPolicies that enforce those settings.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>Both releases are deployed to the same namespace using the current kubectl context. Before running the commands below:</p><ol><li>Verify or set the active namespace: <code>kubectl config set-context --current --namespace=&lt;namespace&gt;</code></li><li>Ensure this is the namespace where you want both releases to run.</li></ol><p><code>dali-release</code> automatically owns the namespace-wide base <code>NetworkPolicy</code> and shared RBAC resources. <code>app-release</code> uses the external Dali endpoint and generates policies only for its active components.</p><p>Use the following commands to start the Dali and app pods, then stop them with the cleanup command below.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dali-release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hpcc/hpcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helm/examples/dali-split-same-namespace/values-dali-only.yaml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hpcc/hpcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helm/examples/dali-split-same-namespace/values-no-dali.yaml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span></span></code></pre></div><p>Expected result:</p><ul><li><code>dali-release</code> creates the only Dali StatefulSet.</li><li><code>app-release</code> creates no Dali StatefulSet.</li><li><code>app-release</code> pods become healthy and use <code>--daliServers=mydali:7070</code>.</li></ul><p>Run the <a href="#end-to-end-validation">end-to-end validation</a> below, then clean up:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dali-release</span></span></code></pre></div><h2 id="end-to-end-validation" tabindex="-1">End-to-end validation <a class="header-anchor" href="#end-to-end-validation" aria-label="Permalink to &quot;End-to-end validation&quot;">​</a></h2><p>After <code>app-release</code> is healthy, run a simple ECL query end-to-end from the app release:</p><ol><li>Access ECL Watch for app release (service created by app release).</li><li>Submit a simple workunit (for example, a trivial <code>OUTPUT(&#39;ok&#39;);</code>).</li><li>Confirm compile and run both succeed.</li></ol><p>You can also validate Dali wiring from pod args:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;--daliServers=&quot;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>values-no-dali.yaml</code> sets <code>dali: []</code> to remove the chart&#39;s default Dali entry. This prevents the app release from creating a local Dali StatefulSet and from owning the shared Dali policies and RBAC resources.</li><li>If <code>dali: []</code> is set and <code>global.externalDaliSvc</code> is not set, template rendering fails for components that require Dali.</li><li>Set <code>global.externalDaliSvc</code> only in the app release&#39;s values file (<code>values-no-dali.yaml</code>), pointing it at the Dali service endpoint created by the Dali-only release. <code>externalDaliSvc</code> accepts a <code>host:port</code> endpoint; this example uses the same-namespace shorthand <code>mydali:7070</code>, while a Dali service in another namespace can use <code>mydali.&lt;dali-namespace&gt;.svc.cluster.local:7070</code>. A component-level <code>externalDaliSvc</code> in the app release values can override the global endpoint.</li><li>This example does not configure a cross-namespace deployment. The generated Dali client and server NetworkPolicies use namespace-scoped pod selectors; provide additional ingress and egress policies for Dali and its clients when they are in different namespaces.</li><li>Namespace-wide base NetworkPolicies and shared RBAC resources are generated only by a release with an enabled entry in <code>values.dali[]</code>.</li><li>The <code>prometheusMetricsReporter</code> pod label is applied per-release from that release&#39;s own <code>global.metrics</code> config, so configure <code>global.metrics</code> on every release whose pods should be labeled/scraped. The release containing the enabled local Dali owns the fixed-name <code>hpcc-metrics-prometheus</code><code>NetworkPolicy</code>, so it must also configure a Prometheus sink with <code>settings.autodiscovery: true</code> if metrics scraping is required in the namespace. Use the same scrape port in every release&#39;s Prometheus sink, because the owner-generated policy allows that port for all labeled pods.</li></ul>`,28)])])}const u=a(t,[["render",o]]);export{m as __pageData,u as default};
